int behavior(int *a, unsigned n, int x) {
 int i=0, y=1; const char *s="a\n";
 if (x && n) { y=a[i++]; } else if (x || n) { y=-1; }
 y = x ? y+1 : y-1;
 switch (x) { case 0: y++; case 1: y+=2; break; default: y=0; }
 for (i=0; i<n; ++i) { if (a[i]<0) continue; while (y<x) { ++y; if (y==5) break; } }
 do { --y; } while (y>3);
 if (y<0) goto done;
 y = sizeof(a[i+1]);
 done: return y;
}

